<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <meta name="robots" content="noindex, nofollow">
    <title>Website Under Construction | Omney Safari</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;600;700&family=Playfair+Display:wght@700;800&display=swap" rel="stylesheet">
    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css">
    <style>
        *{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;font-family:'DM Sans',sans-serif;color:#fff;background:linear-gradient(135deg,rgba(6,31,23,.94),rgba(18,55,42,.78)),url('https://images.unsplash.com/photo-1516426122078-c23e76319801?auto=format&fit=crop&w=2000&q=85') center/cover fixed}.construction-card{width:min(720px,100%);padding:clamp(32px,7vw,64px);border:1px solid rgba(255,255,255,.2);border-radius:28px;background:rgba(7,31,23,.78);box-shadow:0 28px 80px rgba(0,0,0,.32);text-align:center;backdrop-filter:blur(10px)}.brand{display:inline-flex;align-items:center;gap:10px;color:#e6bb61;font-size:.78rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.icon{width:78px;height:78px;margin:28px auto 22px;display:grid;place-items:center;border:1px solid rgba(230,187,97,.42);border-radius:24px;background:rgba(230,187,97,.12);color:#e6bb61;font-size:2rem}.construction-card h1{margin:0;font-family:'Playfair Display',serif;font-size:clamp(2.4rem,7vw,4.6rem);line-height:1.02}.construction-card p{max-width:520px;margin:20px auto 0;color:#d6e3db;font-size:1.05rem;line-height:1.7}.status{display:inline-flex;align-items:center;gap:9px;margin-top:30px;padding:9px 15px;border:1px solid rgba(255,255,255,.18);border-radius:999px;background:rgba(255,255,255,.08);font-size:.78rem;font-weight:700}.status:before{content:'';width:8px;height:8px;border-radius:50%;background:#e6bb61;box-shadow:0 0 0 5px rgba(230,187,97,.12)}
    </style>
</head>
<body>
    <main class="construction-card">
        <span class="brand"><i class="fa-solid fa-paw"></i> Omney Safari</span>
        <div class="icon"><i class="fa-solid fa-compass"></i></div>
        <h1>Website under construction</h1>
        <p>We are preparing an unforgettable new way to discover Uganda’s wildlife, landscapes, and culture. Please check back soon.</p>
        <span class="status">A new adventure is taking shape</span>
    </main>
</body>
</html>
